    def __init__(self, maxsize=128):
        self.maxsize = maxsize
        self.ring = Ring()
        self.index = {}
        self.hits = 0
        self.misses = 0

    def get(self, key, default=None):
        node = self.index.get(key, MISSING)
        if node is MISSING:
            return default
        self.ring.unlink(node)
        self.ring.append(node)
        return node.value

    def put(self, key, value):
